const a={ocnal:{baipishu:"Buku Putih",home1:"Buka dunia mata wang digital",home2:"Deposit sekarang",home3:"Nama",home4:"Harga",home5:"Perubahan 24 jam",home6:"Dagangan",home7:"Mulakan sekarang",home8:"Cipta akaun",home9:"Daftar akaun untuk menikmati lebih banyak keistimewaan dan perkhidmatan",home10:"Daftar",home11:"Deposit dana",home12:"Tambah nilai akaun anda dan mula melabur dalam mata wang kripto",home13:"Deposit kripto",home14:"Mula berdagang",home15:"Jual, beli atau salin dagangan dan temui lebih banyak peluang",home16:"Terokai pasaran",home17:"Pasaran mata wang kripto sedang berkembang pesat, merangkumi mata wang digital, teknologi blockchain dan banyak lagi. Peluangnya cerah tetapi pelaburan memerlukan berhati-hati.",home18:"Spot",home19:"Dagangan masa nyata dengan perubahan harga yang pantas.",home20:"Kontrak kekal",home21:"Dagangan kontrak menawarkan leverage untuk potensi pulangan tinggi.",home22:"Opsyen",home23:"Dagangan opsyen menyediakan strategi lindung nilai yang fleksibel untuk mengawal risiko dan menjana pulangan.",home24:"Pelaburan AI",home25:"Rancang dengan yakin. Melabur dengan bijak. Kurangkan kebimbangan.",home26:"Pulangan tahunan tertinggi dalam sejarah",home27:"Semasa",home28:"Tetap",home29:"Beli sekarang",home30:"Semua orang boleh menggunakan mata wang digital",home31:"Daripada pengalaman pertama berdagang kripto hingga pembelian pertama produk kewangan, platform ini membantu anda menjana keuntungan dengan mudah.",home32:"Ketahui tentang kripto",home33:"Pelajari segala-galanya tentang kripto untuk mula melabur",home34:"Soalan lazim",home35:"Sedia untuk memulakan perjalanan kripto anda?",home36:"Apakah itu pertukaran mata wang kripto?",home37:"Pertukaran kripto ialah pasaran digital yang membolehkan pengguna membeli dan menjual mata wang kripto seperti Bitcoin, Ethereum dan Tether. Binance ialah pertukaran terbesar mengikut volum dagangan.",home38:"Apakah produk yang ditawarkan oleh platform?",home39:"Sebagai platform perdagangan kripto terkemuka di dunia, ia kini berkhidmat kepada lebih 150 juta pengguna berdaftar di lebih 180 negara. Dengan yuran rendah, ia menawarkan lebih daripada 350 mata wang kripto untuk didagangkan.<br><br>Di platform ini pengguna boleh:<br><br>1. Berdagang ratusan mata wang digital dan pasangan dagangan.<br><br>2. Membeli dan menjual kripto melalui dagangan spot.<br><br>3. Menjana faedah melalui pengurusan aset kripto.",home40:"Cara berdagang kripto di platform",home41:"Di platform ini anda boleh berdagang ratusan kripto di pasaran spot, niaga hadapan dan opsyen. Daftar akaun, sahkan identiti anda dan deposit atau beli kripto untuk mula berdagang.",home42:"Adakah platform ini selamat?",home43:"Platform ini komited untuk menyediakan persekitaran dagangan yang selamat dan boleh dipercayai. Kami mempunyai teknologi keselamatan canggih dan pasukan berdedikasi untuk melindungi aset anda. Semua aset pengguna disokong 1:1 sepenuhnya.",home44:"Bagaimana jika terlupa kata laluan?",home45:"Klik 'Lupa Kata Laluan' di halaman log masuk untuk menetapkannya semula.",home46:"Mengapa perlu pengesahan identiti?",home47:"Untuk keselamatan dana anda dan mencegah aktiviti pengubahan wang haram, kami perlu memastikan akaun penerimaan dikaitkan dengan identiti semasa anda.",home48:"Pasaran",home49:"Pasaran perdagangan mata wang kripto global menyokong transaksi pelbagai mata wang, menawarkan keselamatan dan kecekapan.",home50:"Akaun saya",home51:"Deposit",home52:"Pengeluaran",home53:"Tukar",home54:"Hangat",home55:"Melabur dalam token baharu yang diterbitkan dan nikmati pulangan berpotensi tinggi",home56:"Berita",home57:"Mengapa pilih kami?",home58:"Dipercayai oleh berjuta-juta pengguna",home59:"Bilangan pengguna",home60:"Unit rakan kongsi",home61:"Yuran transaksi minimum",home62:"Rakan kongsi",home63:"Volum 24 jam",jianguanzhengshu:"Sijil Pengawalseliaan",falvzhengmingshu:"Sijil Perundangan",withdrawNote:"Notis Pengeluaran:<br><br>Masa pemprosesan pengeluaran adalah 24 jam<br><br>Selepas menghantar permintaan pengeluaran dana, dana akan dibekukan kerana pengeluaran sedang diproses dan disimpan sementara oleh sistem. Ini tidak bermakna aset anda hilang atau terdapat sebarang anomali.<br><br>Permintaan pengeluaran token akan dikreditkan dalam masa 12 jam selepas penyerahan. Jika pengeluaran token tidak dikreditkan selepas masa ketibaan yang dijangkakan, sila hubungi perkhidmatan pelanggan dalam talian.<br><br>Pengeluaran amaun besar mesti dilakukan oleh ahli VIP kami. Sila hubungi perkhidmatan pelanggan dalam talian untuk maklumat lanjut."},licai:{zhiyawakuang:"Kewangan AI",zhiyawakuangjiaoyi:"Kewangan AI"}};export{a as default};
